    ["02-10"] = {steps={[1]={npc="Wizbang Cranktoggle", tgt="Wizbang Cranktoggle"}, [2]={npc="Gwennyth Bly'Leggonde", tgt="Gwennyth Bly'Leggonde"}, [3]={node="Auberdine"}, [4]={hint="Sammelt 6 Kriecherbeine und baut sie in Dröhnkiste 827 ein."}, [5]={hint="Sammelt Meereskreaturknochen von der gestrandeten Meereskreatur unmittelbar südlich von Auberdine und kehrt dann mit ihnen zu Gwennyth Bly'Leggonde nach Auberdine zurück."}, [6]={npc="Dröhnkiste 827", npcObj=true}, [7]={npc="Dröhnkiste 827", npcObj=true}, [8]={npc="Gwennyth Bly'Leggonde", tgt="Gwennyth Bly'Leggonde"}, [9]={npc="Gwennyth Bly'Leggonde", tgt="Gwennyth Bly'Leggonde"}, [10]={hint="Bringt 8 Ladungen Eluniterz und das Medaillon von Elura zu Elanaria in Darnassus."}, [11]={npc="Cerellean Whiteclaw", tgt="Cerellean Whiteclaw"}, [12]={hint="Bergt die Meeresschildkrötenüberreste der skelettierten Meeresschildkröte in den Gewässern westlich von Auberdine und sprecht anschließend in Auberdine mit Gwennyth Bly'Leggonde."}, [13]={hint="Besorgt Euch 3 Drescheraugen von den Dunkelküstendreschern im tiefen Meer in der Nähe der Dröhnkiste 411."}, [14]={text="Folge der Straße bis zu diesem Punkt."}, [15]={npc="Thundris Windwirker", tgt="Thundris Windwirker"}, [16]={npc="Thundris Windwirker", tgt="Thundris Windwirker"}, [17]={npc="Tharnariun Treetender", tgt="Tharnariun Treetender"}, [18]={npc="Terenthis", tgt="Terenthis"}, [19]={text="Folge der Straße bis zu diesem Punkt."}, [20]={hint="Fangt einen lebenden tollwütigen Distelbären und bringt ihn zu Tharnariun."}, [21]={hint="Benutzt den Mondstaub des Cenarius mit dem Moonkinstein, um Mondklaue herauszulocken. Danach müsst Ihr Euch Mondklaue stellen und Euch die Kraft des Körpers und des Herzens verdienen, die er besitzt."}, [22]={npc="Asterion", tgt="Asterion"}, [23]={npc="Asterion", tgt="Asterion"}, [24]={hint="Beschafft für Asterion in Bashal'Aran 8 Grell-Ohrringe."}, [25]={npc="Asterion", tgt="Asterion"}, [26]={npc="Asterion", tgt="Asterion"}, [27]={hint="Beschafft das alte Mondstein-Siegel und bringt es Asterion in Bashal'Aran."}, [28]={npc="Asterion", tgt="Asterion"}, [29]={npc="Asterion", tgt="Asterion"}, [30]={npc="Tharnariun Treetender", tgt="Tharnariun Treetender"}, [31]={npc="Tharnariun Treetender", tgt="Tharnariun Treetender"}, [32]={npc="Schildwache Glynda Nal'Shea", tgt="Schildwache Glynda Nal'Shea"}, [33]={npc="Barithras Moonshade", tgt="Barithras Moonshade"}, [34]={npc="GESUCHT: Gurgelbacke!", npcObj=true}, [35]={npc="Gwennyth Bly'Leggonde", tgt="Gwennyth Bly'Leggonde"}, [36]={hint="Reist von Auberdine nach Osten und sucht nach einem großen, roten Kristall entlang der östlichen Bergkette von Dunkelküste. Informiert Schildwache Glynda Nal'Shea in Auberdine über Eure Erkenntnisse."}, [37]={npc="Schildwache Tysha Moonblade", tgt="Schildwache Tysha Moonblade"}, [38]={hint="Studiert die Schrifttafeln, die von Ameth'Aran und ihrem Untergang erzählen, und kehrt dann zur Schildwache Tysha Moonblade in Dunkelküste zurück."}, [39]={hint="Befreit den Geist von Anaya Dawnrunner und bringt ihren Anhänger zu Cerellean Whiteclaw in Auberdine."}, [40]={hint="Sucht sieben Hochgeborenenrelikte und bringt sie Thundris Windwirker in Auberdine."}, [41]={hint="Zerstört das alte Mondstein-Siegel in der uralten Flamme in Ameth'Aran und kehrt dann zu Asterion in Bashal'Aran zurück."}, [42]={hint="Findet und tötet Jai'vhanel. Die schwarze Eule wurde zuletzt nördlich der Ruinen von Ameth'Aran, am Fuß der Berge, gesichtet. Bringt zum Beweis ihres Todes eine ihrer Federn zu Schildwache Glynda Nal'Shea in Auberdine."}, [43]={npc="Schildwache Tysha Moonblade", tgt="Schildwache Tysha Moonblade"}, [44]={npc="Gestrandete Meeresschildkröte", npcObj=true, desc="Geh nach Süden und töte weitere Tollwütige Distelbären, auch bei etwa 38, 60. Hör nach 6-10 auf."}, [45]={hint="Sucht in Dunkelküste nach einem verderbten Furbolglager und kehrt dann zu Terenthis in Auberdine zurück."}, [46]={npc="Gwennyth Bly'Leggonde", tgt="Gwennyth Bly'Leggonde"}, [47]={n