    ["02-11"] = {steps={[1]={node="Sturmwind"}, [2]={npc="Deputy Rainer", tgt="Deputy Rainer"}, [3]={npc="Bauer Furlbrow", tgt="Bauer Furlbrow"}, [4]={npc="Verna Furlbrow", tgt="Verna Furlbrow"}, [5]={npc="Verna Furlbrow", tgt="Verna Furlbrow"}, [6]={hint="Verna Furlbrow in Westfall möchte, dass Ihr ihr 8 Hände voll Hafer bringt.", tag="Optional"}, [7]={npc="Bauer Saldean", tgt="Bauer Saldean"}, [8]={npc="Salma Saldean", tgt="Salma Saldean"}, [9]={npc="Ozwin Ironsprocket", tgt="Ozwin Ironsprocket"}, [10]={npc="Gryan Stoutmantle", tgt="Gryan Stoutmantle"}, [11]={npc="Gryan Stoutmantle", tgt="Gryan Stoutmantle"}, [12]={node="Späherkuppe"}, [13]={npc="Späher Galiaan", tgt="Späher Galiaan"}, [14]={npc="Alba Fairmoon", tgt="Alba Fairmoon"}, [15]={npc="Alba Fairmoon", tgt="Alba Fairmoon"}, [16]={hint="Nutzt das Set für Brunnenwasserproben, um Proben aus den Brunnen auf Jansens Hof und Molsens Hof zu sammeln."}, [17]={hint="Bauer Furlbrow möchte, dass Ihr seine Taschenuhr holt. Sie befindet sich im Kleiderschrank des Bauernhauses auf der Kürbisfarm im Westen.", desc="Mit passendem Kamerawinkel kannst du es von außen plündern."}, [18]={hint="Alba Fairmoon möchtet, dass Ihr 7 Murlockiemen von Longshore an der Küste von Westfall sammelt."}, [19]={npc="Bauer Furlbrow", tgt="Bauer Furlbrow"}, [20]={hint="Bauer Saldean möchte, dass Ihr 20 Erntebehüter tötet."}, [21]={npc="Verna Furlbrow", tgt="Verna Furlbrow"}, [22]={npc="Bauer Saldean", tgt="Bauer Saldean"}, [23]={npc="Alba Fairmoon", tgt="Alba Fairmoon"}, [24]={npc="Alba Fairmoon", tgt="Alba Fairmoon"}, [25]={npc="Alba Fairmoon", tgt="Alba Fairmoon"}, [26]={hint="Tötet 4 Koboldbuddler im Jangoschacht und 6 Minenarbeiter der Flusspfoten im Goldküstensteinbruch."}, [27]={hint="Gryan Stoutmantle möchte, dass Ihr 15 Fallensteller der Defias und 15 Schmuggler der Defias tötet und zu ihm auf die Späherkuppe zurückkehrt."}, [28]={npc="Gryan Stoutmantle", tgt="Gryan Stoutmantle"}, [29]={npc="Gryan Stoutmantle", tgt="Gryan Stoutmantle"}, [30]={npc="Gryan Stoutmantle", tgt="Gryan Stoutmantle", tag="Optional"}, [31]={hint="Bringt 15 rote Lederkopftücher auf die Späherkuppe zu Späher Galiaan."}, [32]={hint="Ozwin Ironsprocket auf Saldeans Hof möchte, dass Ihr ihm 14 Golemisofedern und 5 Gyrostabilisatoren für Erntearbeiter bringt."}, [33]={hint="Gryan Stoutmantle möchte, dass Ihr 15 Plünderer der Defias und 15 Ausplünderer der Defias tötet und zu ihm auf die Späherkuppe zurückkehrt.", tag="Optional", desc="Eigener Umweg, in der Nähe gibt es keine anderen Ziele. Wenn du es eilig hast, überspring es."}, [34]={npc="Alba Fairmoon", tgt="Alba Fairmoon"}, [35]={npc="Späher Galiaan", tgt="Späher Galiaan"}, [36]={npc="Gryan Stoutmantle", tgt="Gryan Stoutmantle", tag="Optional"}, [37]={npc="Ozwin Ironsprocket", tgt="Ozwin Ironsprocket"}, [39]={npc="Baros Alexston", tgt="Baros Alexston"}, [40]={npc="Baros Alexston", tgt="Baros Alexston"}, [41]={npc="Brandur Ironhammer", tgt="Brandur Ironhammer"}, [42]={npc="Tiza Battleforge", tgt="Tiza Battleforge"}, [43]={npc="Foliant der Offenbarung", npcObj=true, desc="Rechtsklicke Foliant der Offenbarung im Rucksack, um die Quest anzunehmen."}, [44]={npc="Tiza Battleforge", tgt="Tiza Battleforge"}, [45]={npc="Tiza Battleforge", tgt="Tiza Battleforge"}, [46]={npc="John Turner", tgt="John Turner"}, [47]={npc="John Turner", tgt="John Turner"}, [48]={npc="John Turner", tgt="John Turner", desc="Hast du weniger als 10 Leinenstoff, kauf welchen im Auktionshaus. Meist ist er billig."}, [49]={npc="John Turner", tgt="John Turner"}, [50]={npc="Tiza Battleforge", tgt="Tiza Battleforge"}, [51]={npc="Tiza Battleforge", tgt="Tiza Battleforge"}, [52]={npc="Muiredon Battleforge", tgt="Muiredon Battleforge"}, [53]={npc="Muiredon Battleforge", tgt="Muiredon Battleforge"}, [54]={npc="Borgus Steelhand", tgt="Borgus Steelhand"}, [55]={npc="Grimand Elmore", tgt="Grimand Elmore"}, [56]={npc="Furen Longbeard", tgt="Furen Longbeard"}, [57]={text="Geh in Sturmwind zum Zwergendistrikt und nimm die T