    ["05-d1"] = {name="Die Halle der Thanen", entrance="Eisenschmiede 27.63, 47.83", pickup="Nimm die Quests für den Dungeon schon bei Dun Morogh und Loch Modan an, dann musst du vorher nicht extra zurück.", pickupS={{"Nimm die Quests für den Dungeon schon bei Dun Morogh und Loch Modan an, dann musst du vorher nicht extra zurück"}}, steps={[1]={npc="Dunkeleisenkarte", npcObj=true, tag="Dungeon-Vorquest"}, [2]={npc="Erdseher Farsen", tgt="Erdseher Farsen", tag="Dungeon-Vorquest"}, [3]={npc="Erdseher Farsen", tgt="Erdseher Farsen"}, [4]={npc="Afadra Dunwall", tgt="Afadra Dunwall"}, [5]={npc="Thom Filch", tgt="Thom Filch"}, [6]={npc="Ghostly Attendant", tgt="Ghostly Attendant"}, [7]={text="Eingang: Die Halle der Thanen"}, [8]={npc="Ghostly Attendant", tgt="Ghostly Attendant"}, [9]={hint="Tötet 15 wütende Erscheinungen und 10 gepeinigte Seelen, und bettet den Geist von Anvilmar zur Ruhe."}, [10]={hint="Sammelt 8 zwergische Erbstücke in der Halle der Thanen."}, [11]={hint="Betretet die Halle der Thanen unter der Altstadt von Ironforge und besorgt den Kopf von Durgen Dirgehammer."}, [12]={npc="Treaty of Understanding", npcObj=true, desc="Rechtsklicke Abkommen des Einvernehmens im Rucksack, um die Quest anzunehmen. Der Endboss setzt bei etwa 35 % Gesundheit Furcht ein. Räum zuerst die Begleiter weg und zieh den Boss dann in den vorherigen Raum. Neben dem Questgeber ist ein Hebel. Zieh ihn, um die Tür zu öffnen, und lauf direkt hinaus."}, [13]={npc="Thom Filch", tgt="Thom Filch"}, [14]={npc="Afadra Dunwall", tgt="Afadra Dunwall"}, [15]={npc="König Magni Bronzebeard", tgt="König Magni Bronzebeard"}, [16]={npc="König Magni Bronzebeard", tgt="König Magni Bronzebeard"}}},
    ["02-12"] = {steps={[1]={npc="Gryth Thurden", tgt="Gryth Thurden"}, [3]={hint="Gebirgsjäger Gravelgaw im südlichen Wachturm möchte, dass Ihr 10 Stonesplitter-Schädelhauer und 10 Stonesplitter-Seher tötet und ihm anschließend Bericht erstattet."}, [4]={npc="Gebirgsjäger Gravelgaw", tgt="Gebirgsjäger Gravelgaw"}, [5]={npc="Gebirgsjäger Wallbang", tgt="Gebirgsjäger Wallbang"}, [6]={hint="Nehmt das Symbol des Lebens und erweckt Narm Faulk in Dun Morogh wieder zum Leben."}, [7]={npc="Jern Hornhelm", tgt="Jern Hornhelm"}, [8]={npc="Brock Stoneseeker", tgt="Brock Stoneseeker"}, [9]={npc="Magmar Fellhew", tgt="Magmar Fellhew"}, [10]={npc="Magmar Fellhew", tgt="Magmar Fellhew"}, [11]={npc="Ausgrabungsleiter Ironband", tgt="Ausgrabungsleiter Ironband"}, [12]={npc="Daryl der Jüngling", tgt="Daryl der Jüngling"}, [13]={hint="Tötet 6 Bergbussarde und kehrt innerhalb von 15 Minuten zu Daryl dem Jüngling in die Weitschreiter-Lodge zurück."}, [14]={npc="Daryl der Jüngling", tgt="Daryl der Jüngling"}, [15]={npc="Daryl der Jüngling", tgt="Daryl der Jüngling"}, [16]={hint="Tötet 5 alte Bergeber und kehrt innerhalb von 12 Minuten zu Daryl dem Jüngling in die Weitschreiter-Lodge zurück."}, [17]={npc="Daryl der Jüngling", tgt="Daryl der Jüngling"}, [18]={npc="Marek Ironheart", tgt="Marek Ironheart"}, [19]={npc="Marek Ironheart", tgt="Marek Ironheart"}, [20]={npc="Bingles Blastenheimer", tgt="Bingles Blastenheimer"}, [21]={npc="Bingles Blastenheimer", tgt="Bingles Blastenheimer"}, [22]={hint="Findet und besiegt den Krokilisken Dolchzahn und holt Mareks Messer zurück."}, [23]={hint="Besorgt 5 Stücke Krokiliskenfleisch und 6 Krokiliskenhäute für Marek Ironheart in der Weitschreiter-Lodge."}, [24]={hint="Sucht Bingles' Werkzeuge und bringt sie ihm zurück. Es sind:"}, [25]={hint="Gebirgsjäger Wallbang im südlichen Wachturm möchte, dass Ihr 10 Schamanen der Splittersteintroggs und 10 Knochenknacker der Splittersteintroggs tötet."}, [26]={npc="Chefingenieur Hinderweir VII.", tgt="Chefingenieur Hinderweir VII."}, [27]={npc="Verdächtiges Fass", npcObj=true}, [28]={npc="Verdächtiges Fass", npcObj=true}, [29]={npc="Chefingenieur Hinderweir VII.", tgt="Chefingenieur Hinderweir VII."}, [30]={npc="Bingles Blastenheimer", tgt="Bingles Blastenheimer"}, [31]={npc="Marek Ironheart", tgt="Marek Ironheart"}, [32]={npc="Marek Ironheart", tgt="Marek Ironheart"}, [33]={hint="Bringt Magmar Fellhew 8 verzierte Steingötzen."}, [34]={npc="Magmar Fellhew", tgt="Magmar Fellhew"}, [35]={npc="Jern Hornhelm", tgt="Jern Hornhelm"}, [36]={npc="Jern Hornhelm", tgt="Jern Hornhelm"}, [37]={npc="Gebirgsjäger Wallbang", tgt="Gebirgsjäger Wallbang"}, [39]={npc="Argos Nightwhisper", tgt="Argos Nightwhisper"}}},
    ["02-13"] = {steps={[1]={npc="Gubber Blump", tgt="Gubber Blump"}, [2]={npc="GESUCHT: Gurgelbacke!", npcObj=true}, [3]={npc="Archäologin Hollee", tgt="Archäologin Hollee"}, [4]={npc="Archäologin Hollee", tgt="Archäologin Hollee"}, [5]={npc="Thundris Windwirker", tgt="Thundris Windwirker"}, [6]={npc="Gorbold Steelhand", tgt="Gorbold Steelhand"}, [7]={npc="Gorbold Steelhand", tgt="Gorbold Steelhand"}, [8]={npc="Gershala Nightwhisper", tgt="Gershala Nightwhisper"}, [9]={npc="Terenthis", tgt="Terenthis"}, [10]={npc="Terenthis", tgt="Terenthis"}, [11]={npc="Geheimnisvoller roter Kristall", npcObj=true}, [12]={npc="Geheimnisvoller roter Kristall", npcObj=true}, [13]={npc="Asterion", tgt="Asterion"}, [14]={npc="Gestrandete Meereskreatur", npcObj=true}, [15]={hint="Beschafft die Schließkassette der SILBERMORGEN und die Schließkassette der NEBELSCHLEIER für Gorbold Steelhand in Auberdine. Beide Gegenstände findet Ihr an Bord der Schiffswracks nördlich des Dorfes."}, [16]={npc="Dröhnkiste 411", npcObj=true}, [17]={npc="Dröhnkiste 411", npcObj=true}, [18]={npc="Gestrandete Meeresschildkröte", npcObj=true}, [19]={text="Folge der Straße bis zu diesem Punkt.", desc="Töte ab jetzt unterwegs alle Mondpirscherwichte und Tollwütigen Distelbären."}, [20]={text="Folge der Straße bis zu diesem Punkt."}, [21]={hint="Geht von Auberdine aus nach Norden zum ersten Wasserfall des Cliffspring und entnehmt aus dem Teich dort eine Probe."}, [22]={hint="Sammelt 6 feine Krebsbrocken für Gubber Blump in Auberdine."}, [23]={npc="Gestrandete Meeresschildkröte", npcObj=true}, [24]={npc="Balthule Shadowstrike", tgt="Balthule Shadowstrike"}, [25]={npc="Balthule Shadowstrike", tgt="Balthule Shadowstrike"}, [26]={hint="Sammelt 4 abgenutzte Pergamentfetzen für Balthule Shadowstrike in der Nähe des Turms von Althalaxx."}, [27]={npc="Balthule Shadowstrike", tgt="Balthule Shadowstrike"}, [28]={npc="Balthule Shadowstrike", tgt="Balthule Shadowstrike"}, [29]={hint="Befreit den Wald von 20 tollwütigen Distel