    ["04-42"] = {steps={[2]={text="Folge der Straße bis zu diesem Punkt."}, [3]={npc="Falstad Wildhammer", tgt="Falstad Wildhammer"}, [4]={npc="Falstad Wildhammer", tgt="Falstad Wildhammer"}, [5]={npc="Greifenmeister Talonaxe", tgt="Greifenmeister Talonaxe"}, [6]={npc="Greifenmeister Talonaxe", tgt="Greifenmeister Talonaxe"}, [7]={npc="Fraggar Thundermantle", tgt="Fraggar Thundermantle"}, [8]={npc="Fraggar Thundermantle", tgt="Fraggar Thundermantle"}, [9]={text="Binde deinen Ruhestein im Gasthaus am Nistgipfel (13.80, 41.60)."}, [10]={hint="Sammelt 15 Wildekinfedern aus dem Hinterland für Erelas Ambersky in Rut'theran."}, [11]={hint="Durchsucht die Käfige in den beiden Dörfern der Witherbark und kehrt dann zu Greifenmeister Talonaxe zurück."}, [13]={hint="Bringt Fraggar Thundermantle in Aerie Peak 5 Troll-Stammeshalsketten."}, [14]={hint="Sprinkle in Gadgetzan möchte, dass Ihr einen violetten Tragan sucht und ihr bringt."}, [15]={hint="Tötet 10 grüne Schlämme sowie 10 jadegrüne Brühschlammer und meldet Euch dann wieder bei Fraggar Thundermantle in Aerie Peak."}, [16]={npc="Fraggar Thundermantle", tgt="Fraggar Thundermantle"}, [17]={npc="Fraggar Thundermantle", tgt="Fraggar Thundermantle"}, [18]={npc="Greifenmeister Talonaxe", tgt="Greifenmeister Talonaxe"}, [19]={npc="Greifenmeister Talonaxe", tgt="Greifenmeister Talonaxe"}, [20]={hint="Überprüft die Oberfläche des Altars von Zul und kehrt dann zu Greifenmeister Talonaxe zurück."}, [21]={npc="OOX-09/HL-Notsignalgeber", npcObj=true, desc="Rechtsklicke OOX-09/HL-Notsignalgeber im Rucksack, um die Quest anzunehmen."}, [22]={npc="Leitroboter OOX-09/HL", tgt="Leitroboter OOX-09/HL"}, [23]={npc="Leitroboter OOX-09/HL", tgt="Leitroboter OOX-09/HL"}, [24]={hint="Eskortiert OOX-09/HL zur Küste jenseits der Aussichtsklippen und meldet Euch dann bei Oglethorpe Obnoticus in Booty Bay."}, [25]={hint="Benutzt den Superschnapper FX, um einen Schnappschuss von Gammerita zu machen, und kehrt dann zu Daryn Lightwind nach Rut'theran zurück."}, [26]={hint="Whiskey Slim in Booty Bay möchte, dass Ihr ihm die Flaschen Pupellyverbos-Portwein bringt, die er verloren hat."}, [28]={npc="Greifenmeister Talonaxe", tgt="Greifenmeister Talonaxe"}, [29]={npc="Greifenmeister Talonaxe", tgt="Greifenmeister Talonaxe"}, [31]={text="Binde deinen Ruhestein im Gasthaus in Thelsamar (35.40, 48.40)."}, [32]={text="Folge der Straße bis zu diesem Punkt."}}},
    ["04-43"] = {steps={[1]={npc="Sigrun Ironhew", tgt="Sigrun Ironhew", tag="Optional"}, [2]={npc="Garek", tgt="Garek", tag="Optional"}, [3]={hint="Benutzt das Zeichen der Erde, um die Amethyst-, Opal- und Diamantsäulen zu aktivieren und die Runensteine zu holen.", tag="Später unterwegs erledigen", desc="Unterwegs erhältst du meist Feuerverzauberungen. Fällt keine, brich die Quest ab."}, [4]={npc="Siegel der Erde", npcObj=true, tag="Optional"}, [5]={npc="Garek", tgt="Garek", tag="Optional"}, [6]={npc="Sigrun Ironhew", tgt="Sigrun Ironhew", tag="Optional"}, [7]={npc="Hölzernes Plumpsklo", npcObj=true}, [8]={hint="Tötet 8 Geologen der Dunkeleisenzwerge und bringt der Person, die im Plumpsklo in der sengenden Schlucht eingesperrt ist, 15 Stücke Seidenstoff."}, [9]={text="Töte Margol den Wüterich, das bringt viel Erfahrung.", tag="Optional"}, [10]={npc="Margols Horn", npcObj=true, desc="Rechtsklicke Margols Horn im Rucksack, um die Quest anzunehmen."}, [11]={npc="Hölzernes Plumpsklo", npcObj=true}, [12]={npc="Hölzernes Plumpsklo", npcObj=true}, [13]={hint="Nehmt die Abschrift von Goodsteels Geschäftsbuch und beschafft Euch dann die darin aufgeführten Gegenstände, ehe Ihr Krinkle Goodsteel in Tanaris aufsucht."}, [14]={npc="Dorius Stonetender", tgt="Dorius Stonetender"}, [15]={npc="Angesengter Brief", npcObj=true}, [16]={npc="Angesengter Brief", npcObj=true}, [17]={npc="Kalaran Windblade", tgt="Kalaran Windblade"}, [18]={npc="Kalaran Windblade", tgt="Kalaran Windblade"}, [19]={npc="Kalaran Windblade", tgt="Kalaran Windblade"}, [20]={npc="Gesucht/Vermisst/Verloren & Gefunden", npcObj=true, tag="Optional"}, [21]={npc="Gesucht/Vermisst/Verloren & Gefunden", npcObj=true}, [22]={npc="Gesucht/Vermisst/Verloren & Gefunden", npcObj=true}, [23]={npc="Hansel Heavyhands", tgt="Hansel Heavyhands"}, [24]={npc="Hansel Heavyhands", tgt="Hansel Heavyhands", tag="Optional"}, [25]={npc="Hansel Heavyhands", tgt="Hansel Heavyhands"}, [26]={npc="Meisterschmied Burninate", tgt="Meisterschmied Burninate"}, [28]={npc="Gebirgsjägerin Pebblebitty", tgt="Gebirgsjägerin Pebblebitty"}, [29]={npc="Gebirgsjägerin Pebblebitty", tgt="Gebirgsjägerin Pebblebitty"}, [30]={npc="Kurator Thorius", tgt="Kurator Thorius"}, [31]={npc="Kurator Thorius", tgt="Kurator Thorius"}, [32]={npc="Kurator Thorius", tgt="Kurator Thorius"}, [33]={npc="Kurator Thorius", tgt="Kurator Thorius"}, [35]={npc="Gebirgsjägerin Pebblebitty", tgt="Gebirgsjägerin Pebblebitty"}, [36]={hint="Sammelt 4 Herzen der Flamme und 4 Kugeln Golemöl und bringt die Gegenstände zu Velarok Windblade."}, [37]={npc="Kalaran Windblade", tgt="Kalaran Windblade"}, [38]={npc="Kalaran Windblade", tgt="Kalaran Windblade"}, [39]={hint="Sucht die Schmiedewindform und das Ausguck-Handfernrohr. Bringt diese Gegenstände zu Zuchtmeister Scrange in der sengenden Schlucht."}, [40]={hint="Tötet 15 Zuchtmeister der Dunkeleisenzwerge und 15 Sklavenhändler der Dunkeleisenzwerge. Kehrt zu Zuchtmeister Scrange zurück, sobald Ihr die Aufgabe erfüllt habt."}, [41]={hint="Hansel Heavyhands möchte, dass Ihr 20 Schwere Kriegsgolems tötet."}, [42]={hint="Hansel Heavyhands möchte, dass Ihr 20 sengende Lavaspinnen in der sengenden Schlucht tötet.", tag="Optional", desc="Eigener Umweg, in der Nähe gibt es keine anderen Ziele. Wenn du es eilig hast, überspring es."}, [43]={hint="Hansel Heavyhands möchte, dass Ihr 20 Incendosaurier tötet."}, [45]={hint="Tief in der Schlackengrube des Kessels in der sengenden Schlucht werdet Ihr den verräterischen Dunkeleisenzwerg, Aufseher Maltorius, finden.", tag="Später unterwegs erledigen"}, [46]={hint="Irgendwo in der Schlackengrube des Kessels findet Ihr die geheimen Pläne des Feurigen Fluxus, die der Aufseher Maltorius stahl. Findet diese Pläne und bringt sie zurück zu Meisterschmied Burninate in der sengenden Schlucht."}, [47]={hint="Bringt 8 mit Thorium beschichtete Dolche zu Velarok Windblade."}, [48]={npc="Sterbender Archäologe", tgt="Sterbender Archäologe"}, [49]={npc="Sterbender Archäologe", tgt="S