    ["05-d11"] = {name="Blackrock Depths", nameA="{a:1584}", entrance="Sengende Schlucht 34.80, 85.30", steps={[1]={npc="Franclorn Forgewright", tgt="Franclorn Forgewright"}, [2]={npc="Franclorn Forgewright", tgt="Franclorn Forgewright"}, [3]={npc="Franclorn Forgewright", tgt="Franclorn Forgewright"}, [4]={text="Eingang: Blackrock Depths"}, [5]={hint="Erschlagt Fineous Darkvire und bergt den großen Hammer Ironfel. Bringt Ironfel zum Schrein von Thaurissan und legt ihn auf die Statue von Franclorn Forgewright."}, [6]={npc="Denkmal für Franclorn Forgewright", npcObj=true}, [7]={npc="König Magni Bronzebeard", tgt="König Magni Bronzebeard"}, [8]={npc="Ragnar Donnerbräu", tgt="Ragnar Donnerbräu"}, [9]={npc="Ragnar Donnerbräu", tgt="Ragnar Donnerbräu"}, [10]={npc="Oralius", tgt="Oralius"}, [11]={npc="Maxwort Uberglint", tgt="Maxwort Uberglint"}, [12]={npc="Cyrus Therepentous", tgt="Cyrus Therepentous"}, [13]={npc="Marshal Maxwell", tgt="Marshal Maxwell", tag="Optional"}}},
