    ["04-46"] = {steps={[1]={npc="Torwa Pathfinder", tgt="Torwa Pathfinder"}, [2]={npc="Torwa Pathfinder", tgt="Torwa Pathfinder"}, [3]={npc="Ein havariertes Floß", npcObj=true, desc="Sammle je 7 rote, blaue, grüne und gelbe Kristalle und hol dir „Ein zerfleddertes Tagebuch\" von den Raptoren."}, [4]={npc="Ein kleines Pack", npcObj=true}, [5]={npc="Ein kleines Pack", npcObj=true}, [6]={hint="Sucht das Gerippe von Lar'korwis letzter Jagdbeute und stehlt einen Teil eines Dreschadongerippes; kehrt dann zu Torwa Pathfinder im Un'Goro Krater zurück."}, [7]={desc="Töte Pflanzen bei etwa 67.7, 30.7, bis du Stufe 49 zur Hälfte hast."}, [8]={npc="Torwa Pathfinder", tgt="Torwa Pathfinder"}, [9]={npc="Torwa Pathfinder", tgt="Torwa Pathfinder"}, [10]={hint="Bringt Torwa Pathfinder in der Nähe des Eingangs zum Un'Goro Krater 2 Ravasaurus-Pheromondrüsen."}, [11]={npc="Torwa Pathfinder", tgt="Torwa Pathfinder"}, [12]={npc="Torwa Pathfinder", tgt="Torwa Pathfinder"}, [13]={hint="Beschwört Lar'korwi mit dem Inhalt von Torwas Beutel und besiegt ihn. Bringt dann Lar'korwis Kopf zu Torwa Pathfinder in der Nähe des Eingangs zum Un'Goro Krater.", tag="Optional", desc="Diese ist schwerer. Du kannst sie für die Rückkehr nach Un'Goro aufheben."}, [14]={npc="Karna Remtravel", tgt="Karna Remtravel"}, [15]={npc="Linken", tgt="Linken"}, [16]={npc="Linken", tgt="Linken"}, [17]={nodeA="{a:541}"}, [18]={npc="Williden Marshal", tgt="Williden Marshal"}, [19]={npc="Williden Marshal", tgt="Williden Marshal"}, [20]={npc="Hol'anyee Marshal", tgt="Hol'anyee Marshal"}, [21]={npc="Spark Nilminer", tgt="Spark Nilminer"}, [22]={npc="J.D. Collie", tgt="J.D. Collie"}, [23]={npc="J.D. Collie", tgt="J.D. Collie"}, [24]={npc="J.D. Collie", tgt="J.D. Collie"}, [25]={npc="J.D. Collie", tgt="J.D. Collie"}, [26]={npc="J.D. Collie", tgt="J.D. Collie"}, [27]={npc="Vorsicht, Pterrordax!", npcObj=true}, [28]={npc="Muigin", tgt="Muigin"}, [29]={npc="Shizzle", tgt="Shizzle"}, [30]={hint="Findet den Standort des nördlichen 