    ["04-47"] = {steps={[1]={npc="Arathandris Silversky", tgt="Arathandris Silversky"}, [2]={npc="Grazle", tgt="Grazle"}, [3]={npc="Greta Mosshoof", tgt="Greta Mosshoof"}, [4]={npc="Eridan Bluewind", tgt="Eridan Bluewind"}, [5]={npc="Taronn Redfeather", tgt="Taronn Redfeather", tag="Optional"}, [6]={hint="Grazle möchte, dass Ihr Euch beweist, indem Ihr 6 Krieger der Totenwaldfelle, 6 Pfadfinder der Totenwaldfelle und 6 Gärtner der Totenwaldfelle besiegt. Kehrt zu ihm in den Süden des Teufelswalds nahe des Smaragdrefugiums zurück, sobald Ihr dies getan habt."}, [7]={npc="Grazle", tgt="Grazle"}, [8]={npc="Grazle", tgt="Grazle"}, [9]={hint="Tötet Xavathras sowie 11 Jadefeuerteufelsanbeter, 9 Jadefeuerschattenpirscher und 9 Jadefeuerschurken. Kehrt zu Eridan Bluewind im Teufelswald zurück, sobald die Aufgabe erledigt ist."}, [10]={hint="Betretet Jaedenar und erschlagt 4 Hunde von Jaedenar, 4 Gardisten von Jaedenar, 6 Adepten von Jaedenar und 6 Kultisten von Jaedenar, bevor Ihr zu Greta Mosshoof im Teufelswald zurückkehrt."}, [11]={npc="Eridan Bluewind", tgt="Eridan Bluewind"}, [12]={npc="Eridan Bluewind", tgt="Eridan Bluewind"}, [13]={npc="Greta Mosshoof", tgt="Greta Mosshoof"}, [14]={npc="Greta Mosshoof", tgt="Greta Mosshoof"}, [15]={hint="Bringt die leere Feldflasche zum Mondbrunnen im Zentrum von Jaedenar und füllt sie, bevor Ihr zu Greta Mosshoof im Teufelswald zurückkehrt."}, [17]={hint="Sucht und zerstört 2 entropische Bestien und 2 entropische Schrecken, während Ihr das Shatter Scar-Tal erforscht. Nachdem Ihr überprüft habt, ob die Krater immer noch mit verderbtem Fel-Wasser gefüllt sind, kehrt zu Taronn Redfeather im Teufelswald zurück.", tag="Optional", desc="Eigener Umweg, in der Nähe gibt es keine anderen Ziele. Wenn du es eilig hast, überspring es."}, [18]={hint="Eridan Bluewind im Teufelswald möchte, dass Ihr Xavaric sowie 8 Jadefeuerhöllenrufer, 8 Jadefeuerverräter und 8 Jadefeuerschwindler tötet. Kehrt zu Eridan zurück, sobald Ihr die Aufgabe erfüllt habt."}, [19]={npc="Flöte des Xavaric", npcObj=true, desc="Rechtsklicke Flöte des Xavaric im Rucksack, um die Quest anzunehmen."}, [20]={hint="Bringt die Flöte von Xavaric und 5 Jadefeuerteufelsbinder zu Eridan Bluewind im südlichen Teil des Teufelswalds."}, [21]={hint="Bringt 15 Einheiten Blutharz zu Arathandris Silversky im Teufelswald."}, [22]={node="Krallenzweiglichtung"}, [23]={npc="Nafien", tgt="Nafien"}, [24]={npc="Nafien", tgt="Nafien", tag="Im Spiel prüfen"}, [25]={hint="Nafien möchte, dass Ihr 6 Höhlenbehüter der Totenwaldfelle, 6 Rächer der Totenwaldfelle und 6 Schamanen der Totenwaldfelle besiegt. Kehrt danach zu ihm in den Norden des Teufelswalds nahe des Eingangs der Holzschlundfeste zurück.", tag="Im Spiel prüfen"}, [26]={npc="Nafien", tgt="Nafien", tag="Im Spiel prüfen"}, [27]={text="Folge der Straße bis zu diesem Punkt."}, [28]={npc="Salfa", tgt="Salfa", tag="Im Spiel prüfen"}, [29]={npc="Donova Snowden", tgt="Donova Snowden"}, [30]={npc="Donova Snowden", tgt="Donova Snowden"}, [31]={npc="Meggi Peppinrocker", tgt="Meggi Peppinrocker"}, [32]={npc="Jessica Redpath", tgt="Jessica Redpath"}, [33]={nodeA="{a:2255}"}}},
    ["04-48"] = {steps={[2]={npc="Pratt McGrubben", tgt="Pratt McGrubben"}, [3]={npc="Troyas Moonbreeze", tgt="Troyas Moonbreeze"}, [4]={npc="Troyas Moonbreeze", tgt="Troyas Moonbreeze"}, [5]={npc="Gregan Brewspewer", tgt="Gregan Brewspewer"}, [6]={npc="Felsbeißer", tgt="Felsbeißer"}, [7]={hint="Sucht nach Gregan Brewspewer im nördlichen Feralas. Lasst Euch von ihm erklären, wie Ihr Euch das Videre-Elixier beschaffen könnt, und kehrt dann zu Donova Snowden nach Winterspring zurück."}, [8]={hint="Aktiviert Troyas Stock und findet den Equinex-Monolithen.", desc="Weiter hinten kannst du hochspringen und abkürzen."}, [9]={npc="Shay Leafrunner", tgt="Shay Leafrunner"}, [10]={npc="Equinex-Monolith", npcObj=true, desc="Benutze den Stab in deinem Rucksack."}, [11]={npc="Equinex-Monolith", npcObj=true}, [12]={npc="Donova Snowden", tgt="Donova Snowden"}, [13]={hint="Bringt Pratt McGrubben in der Festung Feathermoon 10 Wutschrammyetibälge."}, [14]={npc="Pratt McGrubben", tgt="Pratt McGrubben"}, [15]={npc="Pratt McGrubben", tgt="Pratt McGrubben", desc="Droppt beim Töten der Yetis ein Makelloser Yetibalg, rechtsklicke ihn."}, [16]={npc="Troyas Moonbreeze", tgt="Troyas Moonbreeze"}}},
