    [3882] = {n="Knochenklappern", d="Bringt 8 Dinosaurierknochen zu Spark Nilminer im Un'Goro Krater.", tgo={{"Stegodon", "Plattenpanzerstegodon", "Stachelstegodon", "Donnerstampferstegodon", "Junger Dimetrodon", "Dimetrodon", "Alter Dimetrodon"}}},
    [3883] = {n="Eine fremdartige Ökologie", d="Verwendet die Kratzphiole, um damit eine Schwarmbauwandprobe von einer der Schwarmbrutstätten der Gorishi im Un'Goro Krater zu holen. Sucht nach den Kammern mit der hängenden Larvenbrut.\nBringt die Schwarmbauwandprobe zu Hol'anyee Marshal im Un'Goro Krater.", objs={"Gorishi Hive Hatchery"}},
    [3884] = {n="Willidens Tagebuch", d="Bringt das Tagebuch zu Williden Marshal zurück. Er befindet sich irgendwo im Un'Goro Krater."},
    [3903] = {n="Milly Osworth", d="Sprecht mit Milly Osworth."},
    [3904] = {n="Millys Ernte", d="Bringt 8 Kisten mit Millys Ernte zu Milly Osworth in der Nähe der Abtei von Nordhain.", objs={"Millys Ernte"}},
    [3905] = {n="Traubenliste", d="Bringt die Traubenliste zu Bruder Neals in der Abtei von Nordhain."},
    [3908] = {n="Es ist für jeden ein Geheimnis", d="Bringt Linkens Schwert zu Donova Snowden in Winterspring."},
    [3909] = {n="Das Videre-Elixier", d="Sucht nach Gregan Brewspewer im nördlichen Feralas. Lasst Euch von ihm erklären, wie Ihr Euch das Videre-Elixier beschaffen könnt, und kehrt dann zu Donova Snowden nach Winterspring zurück.", tgo={{"Gregan Brewspewer"}}},
    [3912] = {n="Treffen am Grab", d="Geht zum Friedhof außerhalb von Gadgetzan und benutzt dort das Videre-Elixier. Befolgt Donovas übrige Anweisungen, um Gaeriyan zu finden."},
    [3913] = {n="Grabesstille", d="Wenn Ihr auferstanden seid, sucht nach dem Grabstein, von dem Gaeriyan Euch erzählt hat."},
    [3914] = {n="Linkens Schwert", d="Liefert Linkens überragendes Schwert bei Linken im Un'Goro Krater ab."},
    [3941] = {n="Die Hilfe des Gnoms", d="Sucht J.D. Collie in der Höhle in Marshals Zuflucht auf."},
    [3942] = {n="Linkens Andenken", d="Sucht Eridan Bluewind im südlichen Teil des Teufelswalds."},
    [4023] = {n="Eine Kostprobe der Flamme", d="Zeigt Cyrus Therepentous einen Beweis für Eure Nützlichkeit.\nIhr habt so ein Gefühl, dass Cyrus bereits weiß, dass Ihr unwürdig seid.", tgo={{"Rasender Schwarzdrache"}}},
    [4024] = {n="Eine Kostprobe der Flamme", d="Begebt Euch in die Blackrocktiefen und tötet Bael'Gar.\nIhr wisst lediglich, dass der Riese irgendwo in den Blackrocktiefen haust. Vergesst nicht, die veränderte Haut des schwarzen Drachenschwarms mit Bael'Gars Überresten zu benutzen und damit die feurige Essenz einzufangen.\nBringt die eingeschlossene feurige Essenz zu Cyrus Therepentous zurück.", tgo={{"Bael'Gar"}}},
    [4084] = {n="Silberherz", d="Beschafft 11 silbrige Klauen und 1 Eisenstammherz für Eridan Bluewind im Teufelswald.", tgo={{"Wutklauenbär", "Wutklauengrizzly", "Wutklauenraufer", "Teufelspfotenwolf", "Teufelspfotenaasfresser", "Teufelspfotenverheerer", "Todesheuler", "Mongress"}, {"Wanderer der Eisenstämme", "Donnerstampfer der Eisenstämme"}}},
    [4101] = {n="Den Teufelswald säubern", d="Bringt 15 Einheiten Blutharz zu Arathandris Silversky im Teufelswald.", tgo={{"Wucherborkenschinder", "Wucherborkenschredder", "Dessecus"}}},
    [4123] = {n="Das Herz des Berges", d="Bringt das 'Herz des Berges' zu Maxwort Uberglint in der brennenden Steppe.", objs={"Herz des Berges"}},
    [4124] = {n="Der vermisste Kurier", d="Sprecht mit Ginro Hearthkindle in der Festung Feathermoon."},
    [4125] = {n="Der vermisste Kurier", d="Sucht das Boot des Kuriers irgendwo entlang der Küste von Feralas."},
    [4126] = {n="Hurley Pestatem", d="Bringt Ragnar Donnerbräu in Kharanos das gestohlene Donnerbräurezept.", tgo={{"Hurley Pestatem", "Pestatems Spießgeselle"}}},
    [4127] = {n="Havarie", d="Kehrt zur Festung Feathermoon zurück und zeigt Ginro Hearthkindle das gefundene Messer."},
    [4128] = {n="Ragnar Donnerbräu", d="Sprecht mit Ragnar Donnerbräu."},
    [4129] = {n="Das wieder aufgetauchte Messer", d="Bringt Quintis Jonespyre in der Festung Feathermoon das gefundene Messer."},
    [4130] = {n="Psychometrie-Sitzung", d="Sprecht mit Ginro Hearthkindle in der Festung Feathermoon."},
    [4131] = {n="Die Waldpfotengnolle", d="Durchsucht die Lager der Waldpfotengnolle im Süden Feralas nach Hinweisen auf den Verbleib des Kuriers oder seiner Habseligkeiten."},
    [4135] = {n="Die verwundene Tiefe", d="Da Ihr jetzt Raschals letzten bekannten Aufenthaltsort in Erfahrung gebracht habt, setzt Ihr die Suche nach ihm oder seinen sterblichen Überresten in der verwundenen Tiefe fort. Laut Notiz soll dieser Ort südlich der Lager der Waldpfotengnolle liegen."},
    [4141] = {n="Muigin und Larion", d="Sammelt 15 Blutblüten und kehrt zu Muigin zurück.", tgo={{"Blutblütenpeitscher", "Blutblütenschinder", "Blutblütendrescher", "Blutblütenfalle"}}},
    [4142] = {n="Ein Besuch bei Gregan", d="Bringt Gregan Brewspewer in Feralas eine Blutblüte."},
    [4161] = {n="Rezept der Kaldorei", d="Sammelt 7 kleine Spinnenbeine für Zarrin in Dolanaar.", tgo={{"Waldspinne", "Minenspinne", "Giftzahnbrutmutter", "Klippenlauerer", "Holzlauerer", "Waldlauerer", "Heimtückischer Nachtweber", "Moospirscher"}}},
    [4182] = {n="Drachkin-Bedrohung", d="Erschlagt 15 schwarze Brutlinge, 10 Exemplare der schwarzen Großdrachenbrut, 4 schwarze Wyrmkin und 1 Schwarzdrachen. Kehrt zu Helendis Riverhorn zurück, sobald die Aufgabe erledigt ist.", tgo={{"Schwarzer Brutling"}, {"Schwarze Großdrachenbrut"}, {"Schwarzdrache"}, {"Schwarzwyrmkin"}}},
    [4183] = {n="Die wahren Meister", d="Reist nach Seenhain und händigt Magistrat Solomon Helendis Riverhorns Brief aus."},
    [4184] = {n="Die wahren Meister", d="Reist nach Stormwind und tragt Solomons Hilfegesuch dem Hochlord Bolvar Fordragon vor.\nBolvar residiert in der Burg Stormwind."},
    [4185] = {n="Die wahren Meister", d="Sprecht zuerst mit Lady Katrana Prestor, dann mit Hochlord Bolvar Fordragon.", tgo={{"Lady Katrana Prestor"}}},
    [4186] = {n="Die wahren Meister", d="Händigt Bolvars Erlass an Magistrat Solomon in Seenhain aus."},
    [4223] = {n="Die wahren Meister", d="Sprecht mit Marshal Maxwell in der brennenden Steppe."},
    [4224] = {n="Die wahren Meister", d="Sprecht mit dem struppigen John, um etwas über Marshal Windsors Schicksal zu erfahren, und kehrt dann zu Marshal Maxwell zurück, wenn Ihr diese Aufgabe erledigt habt.\nIhr erinnert Euch daran, dass Marshal Maxwell Euch geraten hat, ihn in einer Höhle im Norden zu suchen.", tgo={{"Struppiger John"}}},
    [4241] = {n="Marshal Windsor", d="Reist zum Blackrock im Nordwesten und dann weiter zu den Blackrocktiefen. Findet heraus, was aus Marshal Windsor geworden ist.\nIhr erinnert Euch daran, dass der struppige John sagte, man hätte Windsor in ein Gefängnis verschleppt."},
    [4243] = {n="Chasing A-Me 01", d="Sucht im Un'Goro Krater nach A-Me 01."},
    [4244] = {n="Chasing A-Me 01", d="Sucht ein Mithrilgehäuse und bringt es zu A-Me 01 im Un'Goro Krater.", tgo={{"Clunk", "Schreddereinheit der Frostwolf", "Schreddereinheit der Stormpike", "7:XT"}}},
    [4245] = {n="Chasing A-Me 01", d="Begleitet A-Me 01 zu Karna Remtravel im Un'Goro Krater."},
    [4262] = {n="Übermeister Pyron", d="Erschlagt Übermeister Pyron und kehrt dann zu Jalinda Sprig zurück.\nIhr erinnert Euch an Jalindas Worte, dass Pyron den Steinbruch bewachen würde. Vielleicht solltet Ihr dort nachsehen?", tgo={{"Übermeister Pyron"}}},
    [4265] = {n="Flucht aus dem Schwarmbau", d="Begleitet Raschal sicher aus dem Schwarmbau der Zukk'ash hinaus.\nKehrt zu Ginro Hearthkindle in der Festung Feathermoon zurück und lasst ihn wissen, dass Raschal am Leben ist und dass es ihm gut geht."},
    [4266] = {n="Der Empfang eines Helden", d="Sprecht mit Shandris Feathermoon in der Festung Feathermoon."},
    [4267] = {n="Aufstieg der Silithid", d="Bringt Raschals Bericht zu Gracina Spiritmight in Darnassus."},
    [4283] = {n="FÜNFZIG! Jawoll!", d="Oralius will 50 Medaillons der Blackrock haben. Die Chancen stehen gut, dass man die Medaillons bei den Orcs in der brennenden Steppe findet.", tgo={{"Soldat der Blackrock", "Zauberhexer der Blackrock", "Töter der Blackrock", "Hexenmeister der Blackrock", "Kampfmeister der Blackrock", "Worg der Blackrock", "Glutworg", "Sabbernder Glutworg"}}},
    [4284] = {n="Machtkristalle", d="Sammelt 7 Machtkristalle von jeder Farbe: rot, blau, gelb und grün. Bringt sie zu J. D. Collie in Marshals Zuflucht.", objs={"Roter Machtkristall", "Gelber Machtkristall", "Grüner Machtkristall", "Blauer Machtkristall"}},
    [4285] = {n="Der Nordpylon", d="Findet den Standort des nördlichen Kristallpylonen im Un'Goro Krater.", objs={"Nördlicher Kristallpylon"}},
    [4286] = {n="Feine Sachen", d="Reist in die Blackrocktiefen und holt 20 Dunkeleisengürteltaschen. Kehrt zu Oralius zurück, sobald die Aufgabe erledigt ist. Ihr nehmt an, dass die Dunkeleisenzwerge in den Blackrocktiefen diese 'Gürteltaschen'-Dinger tragen.", tgo={{"Vorarbeiter der Zorneshämmer", "Aufseher der Zorneshämmer", "Gardist der Zorneshämmer", "Fußsoldat der Zorneshämmer", "Soldat der Zorneshämmer", "Sanitäter der Zorneshämmer", "Offizier der Zorneshämmer", "Arbeiter der Schattenschmiede"}}},
    [4287] = {n="Der Ostpylon", d="Findet den Standort des östlichen Kristallpylonen im Un'Goro Krater.", objs={"Östlicher Kristallpylon"}},
    [4288] = {n="Der Westpylon", d="Findet den Standort des westlichen Kristallpylonen.", objs={"Westlicher Kristallpylon"}},
    [4289] = {n="Die Affen von Un'Goro", d="Bringt Torwa Pathfinder am Eingang zum Un'Goro Krater 2 Un'Goro-Gorillapelze, 2 Un'Goro-Stampferpelze und 2 Un'Goro-Donnererpelze.", tgo={{"Un'Goro-Gorilla", "Un'Goro-Gorilla"}, {"Un'Goro-Stampfer"}, {"Un'Goro-Donnerer"}}},
    [4290] = {n="Lar'korwis Mahl", d="Sucht das Gerippe von Lar'korwis letzter Jagdbeute und stehlt einen Teil eines Dreschadongerippes; kehrt dann zu Torwa Pathfinder im Un'Goro Krater zurück.", objs={"Frisches Dreschadongerippe"}},
    [4291] = {n="Lar'korwis Fährte", d="Bringt Torwa Pathfinder in der Nähe des Eingangs zum Un'Goro Krater 2 Ravasaurus-Pheromondrüsen.", tgo={{"Lar'korwi-Weibchen"}}},
    [4292] = {n="Ein Köder für Lar'korwi", d="Beschwört Lar'korwi mit dem Inhalt von Torwas Beutel und besiegt ihn. Bringt dann Lar'korwis Kopf zu Torwa Pathfinder in der Nähe des Eingangs zum Un'Goro Krater.", tgo={{"Lar'korwi"}}},
    [4296] = {n="Schrifttafel der Sieben", d="Bringt Maxwort Uberglint in der brennenden Steppe die Abschrift der Schrifttafel.", objs={"Schrifttafel der Sieben"}},
    [4301] = {n="Der mächtige U'cha", d="Bringt U'chas Pelz zu Torwa Pathfinder am Eingang des Un'Goro Kraters.", tgo={{"U'cha"}}},
    [4321] = {n="Die Sache verstehen", d="Sprecht demnächst mit J. D. Collie."},
    [4341] = {n="Kharan Mighthammer", d="Begebt Euch in die Blackrocktiefen und findet Kharan Mighthammer.\nDer König erwähnte, dass Kharan dort gefangen sei - vielleicht solltet Ihr nach einem Gefängnis Ausschau halten."},
    [4421] = {n="Die Verderbnis der Jadefeuer", d="Tötet Xavathras sowie 11 Jadefeuerteufelsanbeter, 9 Jadefeuerschattenpirscher und 9 Jadefeuerschurken. Kehrt zu Eridan Bluewind im Teufelswald zurück, sobald die Aufgabe erledigt ist.", tgo={{"Jadefeuerteufelsanbeter"}, {"Jadefeuerschattenpirscher"}, {"Jadefeuerschurke"}, {"Xavathras"}}},
    [4441] = {n="Gebundene Urtume", d="Begebt Euch nach Darnassus und verwendet Eridans Phiole, um Euch im Tempel des Mondes eine Phiole mit gesegnetem Wasser zu holen. Kehrt mit der gefüllten Phiole zu Eridan zurück.", objs={"Brunnen des Tempels des Mondes"}},
    [4442] = {n="Geläutert!", d="Sprecht Eridan gleich noch einmal an."},
    [4449] = {n="Eingesperrt!", d="Tötet 8 Geologen der Dunkeleisenzwerge und bringt der Person, die im Plumpsklo in der sengenden Schlucht eingesperrt ist, 15 Stücke Seidenstoff.", tgo={{"Geologe der Dunkeleisenzwerge"}, {}}, objs={"Alteracgranit", "Ramponierte Truhe", "Robuste Truhe"}},
    [4450] = {n="Geschäftsbuch aus Tanaris", d="Nehmt die Abschrift von Goodsteels Geschäftsbuch und beschafft Euch dann die darin aufgeführten Gegenstände, ehe Ihr Krinkle Goodsteel in Tanaris aufsucht.", tgo={{}, {"Glasnetzspinne"}, {}, {"Jarquia"}}, objs={"Goodsteel-Geschäftsbuch", "Beschädigte Kiste"}},
    [4491] = {n="Etwas Hilfe von guten Freunden", d="Führt Ringo zu Spraggle Frock in Marshals Zuflucht.\nFalls Ringo ohnmächtig werden sollte, verwendet Spraggles Feldflasche, um ihn zu beleben."},
    [4492] = {n="Verloren!", d="Sucht Ringo am Feuerfedergrat."},
    [4493] = {n="Der Marsch der Silithiden", d="Sprecht in Gadgetzan mit Alchimist Pestlezugg."},
    [4495] = {n="Ein guter Freund", d="Sucht Iverron an der Höhle im Norden."},
    [4496] = {n="Dschungelei", d="Bringt eine Gorishiduftdrüse und 5 Un'Goro-Erdproben zu Alchimist Pestlezugg in Gadgetzan.", tgo={{"Wespe der Gorishi", "Arbeiter der Gorishi", "Häscher der Gorishi", "Stecher der Gorishi", "Tunnelgräber der Gorishi", "Schwarmwache der Gorishi", "Schwarmkönigin der Gorishi"}, {}}, objs={"Un'Goro-Erdhaufen"}},
    [4501] = {n="Vorsicht, Pterrordax!", d="Tötet 10 Pterrordax und 15 rasende Pterrordax und sprecht dann mit Spraggle Frock in Marshals Zuflucht.", tgo={{"Pterrordax"}, {"Rasender Pterrordax"}}},
    [4502] = {n="Vulkanische Aktivität", d="Sammelt 9 Proben Un'Goro-Asche von den Feuerelementare am Vulkan im Un'Goro Krater ein und bringt die Proben zu Liv Rizzlefix in Ratchet.", tgo={{"Versengender Elementar", "Lebendiges Feuer", "Sturmflamme", "Lodernder Eindringling", "Baron Glutarr"}}},
    [4503] = {n="Shizzles Flieger", d="Sammelt 8 eingesponnene Dimetrodon-Schuppen und 8 eingesponnene Pterrordax-Schuppen für Shizzle in Marshals Zuflucht.", tgo={{"Junger Dimetrodon", "Dimetrodon", "Alter Dimetrodon"}, {"Pterrordaxjunges", "Pterrordax", "Rasender Pterrordax"}}},
    [4504] = {n="Superkleber", d="Sammelt 12 Proben superklebrigen Teer für Tran'rek in Gadgetzan.", tgo={{"Teerbestie", "Teerlauerer", "Teerfürst", "Teerkriecher"}}},
    [4581] = {n="Kayneth Stillwind", d="Bringt Shindrells Notiz zu Kayneth Stillwind in Forest Song."},
    [4681] = {n="An Land gespült", d="Bergt die Meeresschildkrötenüberreste der skelettierten Meeresschildkröte in den Gewässern westlich von Auberdine und sprecht anschließend in Auberdine mit Gwennyth Bly'Leggonde.", objs={"Skelettierte Meeresschildkröte"}},
    [4722] = {n="Gestrandete Meeresschildkröte", d="Bringt die Meeresschildkrötenüberreste nach Auberdine zu Gwennyth Bly'Leggonde."},
    [4723] = {n="Gestrandete Meereskreatur", d="Bringt die Meereskreaturknochen nach Auberdine zu Gwennyth Bly'Leggonde."},
    [4725] = {n="Gestrandete Meeresschildkröte", d="Bringt den seltsam markierten Kasten nach Auberdine zu Gwennyth Bly'Leggonde."},
    [4726] = {n="Brutlingessenz", d="Bringt 8 Brutlingessenzen sowie den Draco-Incarcinatrix 900 zu Tinkee Steamboil am Flammenkamm in der brennenden Steppe.", objs={"Brutlingessenz"}},
    [4727] = {n="Gestrandete Meeresschildkröte", d="Bringt die Meeresschildkrötenüberreste nach Auberdine zu Gwennyth Bly'Leggonde."},
    [4728] = {n="Gestrandete Meereskreatur", d="Bringt die Meereskreaturknochen nach Auberdine zu Gwennyth Bly'Leggonde."},
    [4730] = {n="Gestrandete Meereskreatur", d="Bringt die Meereskreaturknochen nach Auberdine zu Gwennyth Bly'Leggonde."},
    [4731] = {n="Gestrandete Meeresschildkröte", d="Bringt den seltsam markierten Kasten nach Auberdine zu Gwennyth Bly'Leggonde."},
    [4732] = {n="Gestrandete Meeresschildkröte", d="Bringt die Meeresschildkrötenüberreste nach Auberdine zu Gwennyth Bly'Leggonde."},
    [4733] = {n="Gestrandete Meereskreatur", d="Bringt die Meereskreaturknochen nach Auberdine zu Gwennyth Bly'Leggonde."},
    [4740] = {n="GESUCHT: Gurgelbacke!", d="Sucht und tötet den Murloc namens Gurgelbacke. Man nimmt an, dass die Kreatur die Hütten der Murlocs am Strand südlich von Auberdine beschützt.\nInformiert Schildwache Glynda Nal'Shea über Gurgelbackes Tod.", tgo={{"Gurgelbacke"}}},
    [4761] = {n="Thundris Windwirker", d="Sprecht mit Thundris Windwirker in Auberdine."},
    [4762] = {n="Der Cliffspring", d="Geht von Auberdine aus nach Norden zum ersten Wasserfall des Cliffspring und entnehmt aus dem Teich dort eine Probe.\nKehrt mit der Cliffspringprobe zu Thundris Windwirker nach Auberdine zurück.", objs={"Cliffspring River Waterfall"}},
    [4763] = {n="Die verderbten Schwarzfelle", d="Füllt die leere Säuberungsschale am Mondbrunnen in Auberdine.\nHolt jeweils eine Probe von Früchten, Nüssen und Getreide aus dem Lager der Schwarzfellfurbolgs im Norden.\nMischt alles in der Schale und stellt diese bei dem Freudenfeuer neben dem Cliffspring auf Höhe des nördlichen Lagers ab und lockt dadurch den Satyrverderber an.\nNehmt den Talisman der Verderbnis und bringt ihn zu Thundris Windwirker in Auberdine.", objs={"Xabraxxis Dämonentasche"}},
    [4811] = {n="Der rote Kristall", d="Reist von Auberdine nach Osten und sucht nach einem großen, roten Kristall entlang der östlichen Bergkette von Dunkelküste. Informiert Schildwache Glynda Nal'Shea in Auberdine über Eure Erkenntnisse.", objs={"Geheimnisvoller roter Kristall"}},
    [4812] = {n="Wenn das Wasser fließt", d="Füllt die leere Wasserröhre am Mondbrunnen von Auberdine und untersucht dann den roten Kristall an der östlichen Bergkette von Dunkelküste.", objs={"Auberdine Mondbrunnen"}},
    [4813] = {n="Die Fragmente im Inneren", d="Informiert Schildwache Glynda Nal'Shea in Auberdine über Eure Erkenntnisse."},
    [4842] = {n="Sonderbare Quellen", d="Befolgt Donova Snowdens Anweisungen und meldet Euch dann wieder bei ihr."},
    [4861] = {n="Wütende Wildekin", d="Findet Jaron Stoneshapers ruiniertes Lager samt dessen Vorräte im südlichen Winterspring."},
    [4863] = {n="Wütende Wildekin", d="Sucht Jaron Stoneshapers zerstörten Wagen."},
    [4864] = {n="Wütende Wildekin", d="Klaubt Jarons Vorräte aus dem Schnee und sucht dann die Wildekin, die das Amulett gestohlen haben, von dem Jaron gesprochen hatte.\nBringt Jaron Stoneshaper in der Lodge in Winterspring dessen Vorräte und das blaugefiederte Amulett.", tgo={{}, {"Wahnsinnige Eulenbestie", "Mondbestrahlte Eulenbestie", "Berserkereulenbestie", "Wächter von Elune"}}, objs={"Jarons Laden"}},
    [4901] = {n="Wächter des Altars", d="Schützt Ranshalla, während sie versucht, den Altar von Elune wieder zu aktivieren. Berichtet Erelas Ambersky in Rut'theran von Eurem Fund."},
    [4902] = {n="Wildekin von Elune", d="Sprecht mit Erzdruide Fandral Staghelm in Darnassus."},
    [4906] = {n="Weitere Verderbnis", d="Eridan Bluewind im Teufelswald möchte, dass Ihr Xavaric sowie 8 Jadefeuerhöllenrufer, 8 Jadefeuerverräter und 8 Jadefeuerschwindler tötet. Kehrt zu Eridan zurück, sobald Ihr die Aufgabe erfüllt habt.", tgo={{"Jadefeuerhöllenrufer"}, {"Jadefeuerverräter"}, {"Jadefeuerschwindler"}, {"Xavaric"}}},
    [4971] = {n="Eine Frage der Zeit", d="Benutzt den Temporalversetzer in der Nähe eines der Silos von Andorhal, um die temporalen Parasiten aufzuspüren.\nTötet 15 temporale Parasiten und bringt dann den Temporalversetzer zu Chromie im Gasthaus Andorhal in den Westlichen Pestländern.", tgo={{"Temporaler Parasit"}}},
    [4984] = {n="Die Tierwelt leidet auch", d="Tötet 8 kranke Wölfe und kehrt dann zu Mulgris Deepriver auf dem trostlosen Feld in den Westlichen Pestländern zurück.", tgo={{"Kranker Wolf"}}},
    [4985] = {n="Die Tierwelt leidet auch", d="Tötet 8 kranke Grizzlys und kehrt dann zu Mulgris Deepriver auf dem trostlosen Feld in den Westlichen Pestländern zurück.", tgo={{"Kranker Grizzly"}}},
    [4986] = {n="Glyphenverzierter Eichenast", d="Nach der Magie zu urteilen, mit der der glyphenverzierte Eichenast erfüllt ist, hatte der Taurendruide wohl gewollt, dass Ihr den Ast zum Zirkel des Cenarius nach Darnassus bringt. Bittet einen der Druiden dort um Hilfe."},
    [5021] = {n="Besser spät als nie", d="Das wilde Gebrabbel der Geisterfrau deutete darauf hin, dass sie ein Paket ausliefern musste. Sie behauptete, dass es dort war, wo auch ihr Pferd war. Darüber, wo das Pferd jetzt ist oder wohin das Paket ausgeliefert werden muss, sagt der Geist nichts."},
    [5022] = {n="Besser spät als nie", d="Wendet Euch an die königlichen Disponenten von Stormwind, um etwas über den Aufenthaltsort von Emma Felstone herauszufinden. Normalerweise findet sich ein Volkszählungsbeamter im Rathaus."},
    [5048] = {n="Emma die Nette", d="Sucht die alte Emma in Stormwind und findet heraus, ob sie tatsächlich Emma Felstone ist. Wenn sie es ist, dann möchte sie vielleicht das Paket haben, das Janice Felstone für sie gepackt hat."},
    [5050] = {n="Glücksbringer", d="Bringt Janice Felstone in den Westlichen Pestländern die Hälfte ihres Glücksbringers zurück."},
    [5066] = {n="Der Ruf zu den Waffen: Die Pestländer!", d="Sucht Kommandant Ashlam Valorfist auf. Sein Stützpunkt befindet sich an der Chillwindspitze, nördlich des Alteracgebirges."},
    [5082] = {n="Bedrohung durch die Winterfelle", d="Donova Snowden in Winterspring möchte, dass Ihr 8 Pfadfinder der Winterfelle, 8 Höhlenbehüter der Winterfelle und 8 Totemiker der Winterfelle erledigt.", tgo={{"Pfadfinder der Winterfelle"}, {"Höhlenbehüter der Winterfelle"}, {"Totemiker der Winterfelle"}}},
    [5083] = {n="Feuerwasser der Winterfelle", d="Bringt das leere Feuerwasserfläschchen zu Donova Snowden in Winterspring."},
    [5084] = {n="Der Verderbnis erliegen", d="Durchsucht das Furbolglager der Totenwaldfelle im nördlichen Teil des Teufelswalds nach einem Hinweis."},
    [5085] = {n="Geheimnisvoller Glibber", d="Berichtet Donova Snowden von Euren Entdeckungen."},
    [5092] = {n="Den Weg räumen", d="Tötet 10 Skelettschinder und 10 sabbernde Ghuls in Sorrow Hill.\nKehrt zu Kommandant Ashlam Valorfist an der Chillwindspitze, Westliche Pestländer, zurück.", tgo={{"Skelettschinder"}, {"Sabbernder Ghul"}}},
    [5097] = {n="Turm um Turm", d="Markiert mit der Signalfackel jeden Turm in Andorhal; Ihr müsst im Eingang jedes Turmes stehen, um ihn erfolgreich zu markieren.\nWenn alle vier Türme markiert sind, bringt Ihr die Signalfackel zu Kommandant Ashlam Valorfist an der Chillwindspitze, Westliche Pestländer, zurück.", tgo={{"Turm 1 von Andorhal"}, {"Turm 2 von Andorhal"}, {"Turm 3 von Andorhal"}, {"Turm 4 von Andorhal"}}},
    [5149] = {n="Pamelas Puppe", d="Sucht Pamelas Puppe."},
    [5152] = {n="Tante Marlene", d="Sprecht mit Marlene, südlich der Ruinen von Andorhal."},
    [5153] = {n="Ein seltsamer Historiker", d="Bringt Josephs Ehering zu Chromie.", objs={"Joseph Redpaths Monument"}},
    [5154] = {n="Die Annalen von Darrowshire", d="Bringt die 'Annalen von Darrowshire' zu Chromie in Andorhal.", objs={"Modriger Foliant"}},
    [5155] = {n="Streitmacht von Jaedenar", d="Betretet Jaedenar und erschlagt 4 Hunde von Jaedenar, 4 Gardisten von Jaedenar, 6 Adepten von Jaedenar und 6 Kultisten von Jaedenar, bevor Ihr zu Greta Mosshoof im Teufelswald zurückkehrt.", tgo={{"Hund von Jaedenar"}, {"Wächter von Jaedenar"}, {"Adept von Jaedenar"}, {"Kultist von Jaedenar"}}},
    [5156] = {n="Die Verderbnis überprüfen", d="Sucht und zerstört 2 entropische Bestien und 2 entropische Schrecken, während Ihr das Shatter Scar-Tal erforscht. Nachdem Ihr überprüft habt, ob die Krater immer noch mit verderbtem Fel-Wasser gefüllt sind, kehrt zu Taronn Redfeather im Teufelswald zurück.", tgo={{"Entropische Bestie"}, {"Entropischer Schrecken"}}},
    [5157] = {n="Verderbtes Wasser sammeln", d="Bringt die leere Feldflasche zum Mondbrunnen im Zentrum von Jaedenar und füllt sie, bevor Ihr zu Greta Mosshoof im Teufelswald zurückkehrt.", objs={"der verderbte Mondbrunnen von Jaedenar"}},
    [5158] = {n="Spirituelle Hilfe suchen", d="Bringt das verderbte Mondbrunnenwasser in das Brachland zu Islen Waterseer."},
    [5159] = {n="Gesäubertes Wasser wird zum Teufelswald gebracht", d="Bringt das geläuterte Mondbrunnenwasser zu Greta Mosshoof im Teufelswald."},
    [5168] = {n="Helden von Darrowshire", d="Bringt Davils Buchband und Redpaths Schild zu Carlin Redpath.", objs={"Davils Buchband", "Redpaths Schild"}},
    [5181] = {n="Bösewichte von Darrowshire", d="Bringt den Schädel von Horgus und das zertrümmerte Schwert von Marduk zu Carlin Redpath in der Kapelle des hoffnungsvollen Lichts.", objs={"Horgus' Schädel", "Zertrümmertes Schwert von Marduk"}},
    [5210] = {n="Bruder Carlin", d="Bringt die erweiterten 'Annalen von Darrowshire' zu Carlin Redpath in den Östlichen Pestländern."},
    [5211] = {n="Verteidiger von Darrowshire", d="Befreit 15 Geister von Darrowshire und kehrt dann zu Carlin Redpath zurück.", tgo={{"Geist von Darrowshire"}}},
    [5215] = {n="Die Geißelkessel", d="Sprecht mit der Hohepriesterin MacDonnell an der Chillwindspitze, Westliche Pestländer."},
    [5216] = {n="Ziel: Teufelssteinfeld", d="Geht zum Teufelssteinfeld im den Westlichen Pestländern. Sucht nach dem dortigen Kessellord und besiegt ihn. Er könnte einen Schlüssel haben, der den Zugang zu dem Kessel ermöglicht. Ihr müsst die leere Flasche: Teufelssteinfeld bei Euch haben, um eine Probe des Giftes zu entnehmen, das sich in dem Kessel findet.", tgo={{"Kessellord Gallenschlund"}}},
    [5217] = {n="Rückkehr zum Chillwind-Lager", d="Bringt die gefüllte Flasche: Teufelssteinfeld zur Hohepriesterin MacDonnell an der Chillwindspitze, Westliche Pestländer."},
    [5219] = {n="Ziel: Dalsons Tränenfeld", d="Begebt Euch zu Dalsons Tränenfeld in den Westlichen Pestländern, um den dortigen Kessellord zu suchen und zu besiegen. Verwendet dann seinen Schlüssel, um Zugang zum Kessel zu erhalten. Ihr müsst die leere Flasche: Dalsons Tränenfeld bei Euch haben, um eine Probe des Giftes zu entnehmen, das sich in dem Kessel findet.", tgo={{"Kessellord Malvinius"}}},
    [5220] = {n="Rückkehr zum Chillwind-Lager", d="Bringt die gefüllte Flasche: Dalsons Tränenfeld zur Hohepriesterin MacDonnell an der Chillwindspitze, Westliche Pestländer."},
    [5222] = {n="Ziel: Das trostlose Feld", d="Begebt Euch zum trostlosen Feld in den Westlichen Pestländern, um den dortigen Kessellord zu suchen und zu besiegen. Verwendet dann seinen Schlüssel, um Zugang zum Kessel zu erhalten. Ihr müsst die leere Flasche: Das trostlose Feld bei Euch haben, um eine Probe des Giftes zu entnehmen, das sich in dem Kessel findet.", tgo={{"Kessellord Razarch"}}},
    [5223] = {n="Rückkehr zum Chillwind-Lager", d="Bringt die gefüllte Flasche: Das trostlose Feld zur Hohepriesterin MacDonnell an der Chillwindspitze, Westliche Pestländer."},
    [5225] = {n="Ziel: Gahrrons Trauerfeld", d="Begebt Euch zu Gahrrons Trauerfeld in den Westlichen Pestländern, um den dortigen Kessellord zu suchen und zu besiegen. Verwendet dann seinen Schlüssel, um Zugang zum Kessel zu erhalten. Ihr müsst die leere Flasche: Gahrrons Trauerfeld bei Euch haben, um eine Probe des Giftes zu entnehmen, das sich in dem Kessel findet.", tgo={{"Kessellord Rachseele"}}},
    [5226] = {n="Rückkehr zum Chillwind-Lager", d="Bringt die gefüllte Flasche: Gahrrons Trauerfeld zur Hohepriesterin MacDonnell an der Chillwindspitze, Westliche Pestländer."},
    [5238] = {n="Mission erfüllt!"},
    [5241] = {n="Onkel Carlin", d="Sucht Carlin Redpath."},
    [5244] = {n="Die Ruinen von Kel'Theril", d="Sprecht mit Jaron Stoneshaper in Starfall."},
    [5245] = {n="Die gequälten Seelen von Kel'Theril", d="Benutzt Jarons Hacke, um die vier Fragmente des Hochgeborenenrelikts zu suchen. Bringt sie zu Aurora Skycaller in den Östlichen Pestländern.", objs={"Fragment eines Hochgeborenenrelikts"}},
    [5246] = {n="Fragmente der Vergangenheit", d="Sucht die hochheiligen Schriften der Hochgeborenen im Tempel von Zin-Malor in Azshara und bringt sie zu Aurora Skycaller beim Nordpassturm in den östlichen Pestländern.", objs={"Hochheilige Schriften der Hochgeborenen"}},
    [5250] = {n="Starfall", d="Sucht Starfall in Winterspring und sprecht mit Wynd Nightchaser."},
    [5261] = {n="Eagan Peltskinner", d="Sprecht mit Eagan Peltskinner."},
    [5401] = {n="Anstecknadel der Argentumdämmerung"},
    [5541] = {n="Munition für Rumbleshot", d="Bringt Rumbleshots Munition zu Hegnar Rumbleshot in Dun Morogh.", objs={"Munitionskiste"}},
    [5542] = {n="Dämonenhunde", d="Erschlagt 20 kleine Seuchenhunde, 5 Seuchenhunde und 5 rasende Seuchenhunde. Kehrt zu Tirion Fordring zurück, sobald Ihr die Aufgabe erfüllt habt.", tgo={{"Kleiner Seuchenhund"}, {"Seuchenhund"}, {"Rasender Seuchenhund"}}},
    [5543] = {n="Blutgefärbter Himmel", d="Erschlagt 30 Seuchenfledermäuse und kehrt zu Tirion Fordring zurück.", tgo={{"Seuchenfledermaus"}}},
    [5544] = {n="Aassammlung", d="Sucht nach den Aaslarven und Aasverschlingern dieses Gebiets. Erschlagt sie und sammelt ihr Fleisch. Kehrt zu Tirion Fordring zurück, wenn Ihr 15 Scheiben Aaswurmfleisch gesammelt habt.", tgo={{"Aaslarve", "Aasverschlinger"}}},
    [5545] = {n="Ein Bündel Probleme", d="Bringt 8 Holzbündel zu Raelen beim Holzfällerlager des Osttals.", objs={"Kleinholzbündel"}},
    [5601] = {n="Schwester Pamela", d="Sucht Pamela Redpath in Darrowshire."},
    [5713] = {n="Ein Schuss, ein Treffer", d="Schützt die Schildwache Aynasha und sprecht dann mit Onaeya bei Maestras Posten in Ashenvale."},
    [5742] = {n="Erlösung", d="Hört Euch an, was Tirion Fordring zu sagen hat.", tgo={{"Tirion Fordring"}}},
    [5762] = {n="Hemet Nesingwary", d="Bringt Kravels Kiste zu Hemet Nesingwary ins Schlingendorntal."},
    [5781] = {n="Von vergessenen Erinnerungen", d="Begebt Euch zum Tiefgewölbe im südlichsten Abschnitt der Östlichen Pestländer und sucht nach Taelans Hammer. Kehrt zu Tirion Fordring zurück, sobald Ihr Eure Mission abgeschlossen habt.", tgo={{"Mercutio Dreckschipper"}}},
    [5845] = {n="Von verlorener Ehre", d="Reist nach Northdale im nordöstlichsten Gebiet der Östlichen Pestländer und sucht nach dem Symbol der verlorenen Ehre. Kehrt zu Tirion Fordring zurück, sobald Ihr Eure Mission abgeschlossen habt.", objs={"Symbol der verlorenen Ehre"}},
    [5846] = {n="Von Liebe und Familie", d="Begebt Euch zur Insel Caer Darrow im südlich-zentralen Bereich der Pestländer und sucht nach Hinweisen, wo sich das Gemälde befinden könnte."},
    [5848] = {n="Von Liebe und Familie", d="Begebt Euch nach Stratholme im nördlichen Teil der Pestländer. In der Scharlachroten Bastion findet Ihr das Gemälde 'Von Liebe und Familie', das zwischen anderen Gemälden versteckt ist und auf dem die Zwillingsmonde unserer Welt abgebildet sind.\nBringt das Gemälde zu Tirion Fordring.", objs={"Unvollendetes Gemälde"}},
    [5863] = {n="Das Truppenlager der Dünenbrecher", d="Andi Lynn in Gadgetzan möchte, dass Ihr das Truppenlager der Dünenbrecher vernichtet, indem Ihr 10 Schläger der Dünenbrecher 10 Vollstrecker der Dünenbrecher sowie Gor'marok den Verheerer tötet.", tgo={{"Schläger der Dünenbrecher"}, {"Vollstrecker der Dünenbrecher"}, {"Gor'marok der Verheerer"}}},
    [5903] = {n="Eine Plage komme über Euch", d="Wendet den leeren Termitenkrug auf die Termitenhügel in den Östlichen Pestländern an. Sobald Ihr 100 Pestland-Termiten gesammelt habt, kehrt zu Nathaniel Dumah am Chillwindposten in den Westlichen Pestländern zurück.", objs={"Großer Termitenhügel"}},
    [5904] = {n="Eine Plage komme über Euch", d="Sucht Euch einen geeigneten Ort in der Mitte des Northridge-Sägewerks in den Westlichen Pestländern, um das Fass mit den Pestland-Termiten abzustellen."},
    [6001] = {n="Körper und Herz", d="Benutzt den Mondstaub des Cenarius mit dem Moonkinstein, um Mondklaue herauszulocken. Danach müsst Ihr Euch Mondklaue stellen und Euch die Kraft des Körpers und des Herzens verdienen, die er besitzt.\nSprecht mit Mathrengyl Bearwalker in Darnassus, wenn Ihr fertig seid.", tgo={{"Geist von Mondklaue"}}},
    [6004] = {n="Offene Rechnungen", d="Tötet 2 scharlachrote Sanitäter, 2 scharlachrote Jäger, 2 scharlachrote Magi und 2 scharlachrote Ritter, bevor Ihr zu Kirsta Deepshadow in den Westlichen Pestländern zurückkehrt.", tgo={{"Scharlachrote Sanitäterin"}, {"Scharlachroter Jäger"}, {"Scharlachroter Magier"}, {"Scharlachroter Ritter"}}},
    [6021] = {n="Zaeldarr der Ausgestoßene", d="Bringt Zaeldarrs Kopf zu Verwalter Alen in der Kapelle des hoffnungsvollen Lichts.", tgo={{"Zaeldarr der Ausgestoßene"}}},
    [6023] = {n="Offene Rechnungen", d="Besiegt Jägerin Radley und Chevalier Durgen, bevor Ihr zu Kirsta Deepshadow in den Westlichen Pestländern zurückkehrt.", tgo={{"Jägerin Radley"}, {"Chevalier Durgen"}}},
    [6024] = {n="Hameyas Bitte", d="Tötet Spitzel Hameya. Benutzt seinen Schlüssel bei dem Erdhaufen hinter dem Tiefgewölbe.", tgo={{"Spitzel Hameya"}}},
    [6025] = {n="Offene Rechnungen", d="Geht nach Hearthglen, sucht einen hohen Aussichtspunkt, von dem aus Ihr die Stadt überblicken könnt, schätzt die Streitkräfte des Scharlachroten Kreuzzugs und kehrt dann zu Kirsta Deepshadow in den Westlichen Pestländern zurück."},
    [6028] = {n="Der Everlook-Bericht", d="Bringt den Everlook-Bericht zu Argentumoffizier Pureheart im Chillwind-Lager in den westlichen Pestländern."},
    [6030] = {n="Fürst Nicholas Zverenhoff", d="Bringt das Buch 'Studien zur Geistersuche' zu Fürst Nicholas Zverenhoff in der Kapelle des hoffnungsvollen Lichts in den Östlichen Pestländern."},
    [6063] = {n="Die Zähmung der Bestie", d="Benutzt die Zähmrute, um einen Waldweberlauerer zu zähmen. Übt Eure Fertigkeiten und bringt die Zähmrute dann zu Dazalar in Dolanaar.", tgo={{"Waldweberlauerer"}}},
    [6064] = {n="Die Zähmung der Bestie", d="Benutzt die Zähmrute, um einen großen Klippeneber zu zähmen. Übt Eure Fertigkeiten und bringt die Zähmrute dann zu Grif Wildheart in Kharanos.", tgo={{"Großer Klippeneber"}}},
    [6084] = {n="Die Zähmung der Bestie", d="Benutzt die Zähmrute, um einen Schneeleoparden zu zähmen. Übt Eure Fertigkeiten und kehrt dann zu Grif Wildheart in Kharanos zurück.", tgo={{"Schneeleopard"}}},
    [6085] = {n="Die Zähmung der Bestie", d="Benutzt die Zähmrute, um einen Eisklauenbären zu zähmen. Übt Eure Fertigkeiten und bringt die Zähmrute dann zu Grif Wildheart in Kharanos.", tgo={{"Eisklauenbär"}}},
    [6086] = {n="Die Ausbildung des Tiers", d="Sprecht mit Belia Thundergranite in Ironforge."},
    [6101] = {n="Die Zähmung der Bestie", d="Benutzt die Zähmerrute, um einen pirschenden Nachtsäbler zu zähmen. Übt Eure Fertigkeiten und bringt die Zähmrute dann zu Dazalar in Dolanaar.", tgo={{"Pirschender Nachtsäbler"}}},
    [6102] = {n="Die Zähmung der Bestie", d="Benutzt die Zähmrute, um einen Strigidkreischer zu zähmen. Übt Eure Fertigkeiten und bringt die Zähmrute dann zu Dazalar in Dolanaar.", tgo={{"Strigidkreischer"}}},
    [6103] = {n="Die Ausbildung des Tiers", d="Sprecht mit Jocaste in der Enklave des Cenarius in Darnassus."},
    [6134] = {n="Geisterplasmasuche", d="Bringt 8 Einheiten Geisterplasma und die Kiste mit den Geistermagneten zu Hornizz Brimbuzzle in Desolace.", tgo={{"Zentaurengeist"}}},
    [6182] = {n="Der Erste und Letzte", d="Sprecht mit Meister Mathias Shaw in der Altstadt von Stormwind. Er wohnt in der Kaserne."},
    [6183] = {n="Ehret die Toten", d="Sprecht wieder mit Mathias Shaw, wenn Ihr seine Aufgabe annehmen wollt."},
    [6184] = {n="Flint Shadowmore", d="Reist zur Chillwindspitze in den Westlichen Pestländern und trefft Euren Kontaktmann Flint Shadowmore."},
    [6185] = {n="Die östlichen Pestländer", d="Sucht in den östlichen Pestländern nach Hinweisen auf den 'Blightcaller' und die vermissten SI:7-Agenten. Wenn Ihr SI:7-Insignien findet, bringt sie zu Flint Shadowmore an der Chillwindspitze.", objs={"Zerfleischte menschliche Überreste"}},
    [6341] = {n="Die Arten von Teldrassil", d="Bringt Nessas Sammlung zu Vesprystus."},
    [6342] = {n="Flug nach Auberdine", d="Bucht bei Hippogryphenmeister Vesprystus einen Hippogryphen nach Auberdine und bringt dann Nessas Sammlung zu Laird."},
    [6343] = {n="Rückkehr zu Nessa", d="Bringt Lairds Antwort zu Nessa Shadowsong."},
    [6344] = {n="Nessa Shadowsong", d="Sprecht mit Nessa Shadowsong."},
    [6387] = {n="Ehrenstudenten", d="Bringt Brocks Liste zu Thorgrum Borrelson in Thelsamar."},
    [6388] = {n="Gryth Thurden", d="Bringt die Ehrenhacken zu Gryth Thurden in Ironforge."},
    [6389] = {n="Eine Plage komme über Euch", d="Befreit die Pestländer-Termiten im Sägewerk von Northridge, dann kehrt mit dem Fass Pestländer-Termiten zu Nathaniel Dumah im Chillwind-Posten in den westlichen Pestländern zurück."},
    [6391] = {n="Flug nach Ironforge", d="Bucht einen Greifen nach Ironforge von Greifenmeister Thorgrum Borrelson, dann bringt Brocks Liste zu Golnir Bouldertoe in Ironforge."},
    [6392] = {n="Rückkehr zu Brock", d="Bucht einen Greifen nach Thelsamar bei Greifenmeister Gryth Thurden, dann bringt die Ehrenhacken zu Brock Stoneseeker in Thelsamar."},
    [6603] = {n="Probleme in Winterspring", d="Findet Donova Snowden bei den Thermalquellen in Winterspring."},
    [6604] = {n="Wütende Wildekin", d="Sprecht mit Jaron Stoneshaper in Starfall."},
    [7383] = {n="Krone der Erde", d="Füllt die Amethystphiole und bringt sie Corithras Moonrage in Dolanaar.", objs={"Lichtung des Orakels'-Mondbrunnen"}},
    [7701] = {n="GESUCHT: Vorarbeiter Maltorius", d="Tief in der Schlackengrube des Kessels in der sengenden Schlucht werdet Ihr den verräterischen Dunkeleisenzwerg, Aufseher Maltorius, finden.\nTötet den Aufseher Maltorius und nehmt seinen Kopf an Euch. Bringt diesen zum Ausguck Captain Lolo Longstriker in der sengenden Schlucht für eine Belohnung.", tgo={{"Aufseher Maltorius"}}},
    [7722] = {n="Was zum Fluxus?!", d="Irgendwo in der Schlackengrube des Kessels findet Ihr die geheimen Pläne des Feurigen Fluxus, die der Aufseher Maltorius stahl. Findet diese Pläne und bringt sie zurück zu Meisterschmied Burninate in der sengenden Schlucht.", objs={"Geheimpläne: Feuriger Fluxus"}},
    [7723] = {n="Verdammt seien diese fetten Finger", d="Hansel Heavyhands möchte, dass Ihr 20 Schwere Kriegsgolems tötet.\nDie Schweren Kriegsgolems wandern in der Gegend um den Kessel in der sengenden Schlucht herum. Sobald Ihr genug getötet habt, kehrt zu Hansel zurück.", tgo={{"Schwerer Kriegsgolem"}}},
    [7724] = {n="Feurige Bedrohung!", d="Hansel Heavyhands möchte, dass Ihr 20 sengende Lavaspinnen in der sengenden Schlucht tötet.\nDie sengenden Lavaspinnen findet Ihr auf den Plateaus und in den Lavabecken der sengenden Schlucht. Sobald Ihr genug getötet habt, kehrt zu Hansel zurück.", tgo={{"Versengende Lavaspinne"}}},
    [7727] = {n="Incendosaurier? Was-auch-immer-Saurier?", d="Hansel Heavyhands möchte, dass Ihr 20 Incendosaurier tötet.\nDie Incendosaurier haben sich in den Lavabecken der Schlackengrube eingenistet. Ihr findet die Schlackengrube im Kessel der segenden Schlucht.\nSobald Ihr genug Incendosaurier getötet habt, kehrt zu Hansel Heavyhands in der sengenden Schlucht zurück.", tgo={{"Incendosaurier"}}},
    [7728] = {n="GESTOHLEN: Schmiedewindform und ein Ausguck-Handfernrohr", d="Sucht die Schmiedewindform und das Ausguck-Handfernrohr. Bringt diese Gegenstände zu Zuchtmeister Scrange in der sengenden Schlucht.\nDie einzigen Informationen die Ihr habt sind: Die Schmiedewindform is ein SCHMIEDEwerkzeug welches von SCHMIEDEN verwendet wird und das Ausguck-Handfernrohr ist ein unverzichtbares Werkzeug für SPÄHPOSTEN.", tgo={{"Dampfschmied der Dunkeleisenzwerge"}, {"Ausguck der Dunkeleisenzwerge"}}},
    [7729] = {n="STELLE ZU VERGEBEN: Erledige die Konkurrenz", d="Tötet 15 Zuchtmeister der Dunkeleisenzwerge und 15 Sklavenhändler der Dunkeleisenzwerge. Kehrt zu Zuchtmeister Scrange zurück, sobald Ihr die Aufgabe erfüllt habt.", tgo={{"Zuchtmeister der Dunkeleisenzwerge"}, {"Sklavenhändler der Dunkeleisenzwerge"}}},
    [7733] = {n="Beste Qualität", d="Bringt Pratt McGrubben in der Festung Feathermoon 10 Wutschrammyetibälge.", tgo={{"Wutschrammyeti", "Alter Wutschrammyeti", "Wilder Wutschrammyeti", "Lauernder Wildschrammyeti"}}},
    [7735] = {n="Makelloser Yetibalg", d="Bringt Pratt McGrubben in der Festung Feathermoon den makellosen Yetibalg."},
    [7791] = {n="Spendet Wolle", d="Benutzen/Sammeln: Alteracgranit, Ramponierte Truhe, Ramponierte Truhe", objs={"Alteracgranit", "Ramponierte Truhe", "Ramponierte Truhe"}},
    [7793] = {n="Spendet Seide", d="Benutzen/Sammeln: Alteracgranit, Ramponierte Truhe, Robuste Truhe", objs={"Alteracgranit", "Ramponierte Truhe", "Robuste Truhe"}},
    [8360] = {n="Tanzen für Marzipan", d="Tanzt für Gastwirtin Pala und Ihr werdet im Gegenzug etwas von dem Marzipan aus Thunder Bluff bekommen!", tgo={{"Gastwirtin Pala"}}},
    [8365] = {n="Piratenhüte Ahoy!", d="Sammelt 20 Südmeerpiratenhüte und bringt sie zurück zur eingebildeten Modeschöpferin nach Steamwheedle in Tanaris.", tgo={{"Pirat der Südmeerfreibeuter", "Seeräuber der Südmeerfreibeuter", "Dockarbeiter der Südmeerfreibeuter", "Schwadroneur der Südmeerfreibeuter", "Andre Feuerbart", "Kregg Kielhol"}}},
    [8460] = {n="Verbündeter der Holzschlundfeste", d="Grazle möchte, dass Ihr Euch beweist, indem Ihr 6 Krieger der Totenwaldfelle, 6 Pfadfinder der Totenwaldfelle und 6 Gärtner der Totenwaldfelle besiegt. Kehrt zu ihm in den Süden des Teufelswalds nahe des Smaragdrefugiums zurück, sobald Ihr dies getan habt.", tgo={{"Krieger der Totenwaldfelle"}, {"Pfadfinder der Totenwaldfelle"}, {"Gärtner der Totenwaldfelle"}}},
    [8461] = {n="Totenwaldfelle des Nordens", d="Nafien möchte, dass Ihr 6 Höhlenbehüter der Totenwaldfelle, 6 Rächer der Totenwaldfelle und 6 Schamanen der Totenwaldfelle besiegt. Kehrt danach zu ihm in den Norden des Teufelswalds nahe des Eingangs der Holzschlundfeste zurück.", tgo={{"Höhlenbehüter der Totenwaldfelle"}, {"Rächer der Totenwaldfelle"}, {"Schamane der Totenwaldfelle"}}},
    [8462] = {n="Sprecht mit Nafien", d="Reist nach Norden entlang der Hauptstraße des Teufelswalds und sprecht mit einem Furbolg names Nafien. Er hält außerhalb des Eingangs zur Holzschlundfeste Wache."},
    [8464] = {n="Aktivität der Winterfelle", d="Salfa möchte, dass Ihr 8 Schamanen der Winterfelle, 8 Höhlenbehüter der Winterfelle und 8 Ursa der Winterfelle erledigt. Salfa befindet sich direkt außerhalb des Eingangs zur Holzschlundfeste in Winterspring.", tgo={{"Schamane der Winterfelle"}, {"Höhlenbehüter der Winterfelle"}, {"Ursa der Winterfelle"}}},
