    [86758] = {n="Ist dies ein Dolch", d="Findet und besiegt den Krokilisken Dolchzahn und holt Mareks Messer zurück.", tgo={{"Dolchzahn"}}},
    [87288] = {n="Weiche Säblerpelze", d="Bringt Aldria 6 weiche Nachtsäblerpelze.", tgo={{"Nachtsäbler"}}},
