    [91733] = {n="Flussabwärts", d="Sammelt die durchnässte Axt, durchnässte Säge und den durchnässten Werkzeugkasten, die vom Holzfällerlager des Osttals flussabwärts gespült wurden, und kehrt damit zu Ormin Pelford zurück.", objs={"Durchnässte Axt", "Durchnässte Säge", "Durchnässter Werkzeugkasten"}},
    [91740] = {n="Quakis Kopf", d="Bringt Quakis Kopf zu Merell Ross in der Kammwacht."},
    [91741] = {n="Angeknabbertes Buch", d="Bringt das Buch zu Bruder Paxton zurück."},
