    [91772] = {n="Pssst! Wir jagen Kobolde", d="Folgt den Koboldspuren und meldet Euch bei Marshal Dughan in Goldhain mit Euren Erkenntnissen und dem Kobold-Fährtenleseset.", objs={"Kobold Tracks"}},
